"use client";

/* Hallmark · component: cta · genre: editorial · theme: Inspo-paper
 * archetype: Marquee · diversification: motion-led — the action is the
 *   loop, not a button
 * states: default · hover (loop pauses) · prefers-reduced-motion
 * contrast: pass (46-50)
 */

import { useState } from "react";

/**
 * Marquee CTA — a single phrase scrolls left-to-right on infinite
 * loop. The whole strip is clickable. Pauses on hover so the reader
 * can rest their eye; collapses to a static line under reduced-motion.
 */
const PHRASE = "Open the archive — Open the archive — Open the archive —";

export function CtaMarquee() {
  const [paused, setPaused] = useState(false);

  return (
    <a
      href="#"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      className="
        group block overflow-hidden border-y rule bg-[var(--color-link)]
        py-8 text-[var(--color-paper)]
        transition-colors duration-300
        hover:bg-[var(--color-fg)]
      "
      style={{
        maskImage:
          "linear-gradient(to right, transparent, black 4%, black 96%, transparent)",
        WebkitMaskImage:
          "linear-gradient(to right, transparent, black 4%, black 96%, transparent)",
      }}
    >
      <div
        className="flex w-fit gap-12 whitespace-nowrap will-change-transform"
        style={{
          animation: "cta-marquee 18s linear infinite",
          animationPlayState: paused ? "paused" : "running",
        }}
      >
        {/* Three copies so the seam is invisible at any width. */}
        {[0, 1, 2].map((i) => (
          <span
            key={i}
            className="font-display text-3xl tracking-tight sm:text-5xl"
          >
            {PHRASE}
          </span>
        ))}
      </div>
      <style>{`
        @keyframes cta-marquee {
          from { transform: translateX(0); }
          to { transform: translateX(-33.333%); }
        }
        @media (prefers-reduced-motion: reduce) {
          div[style*="cta-marquee"] { animation: none !important; }
        }
      `}</style>
    </a>
  );
}

"use client";

/* Hallmark · component: faq · genre: editorial · theme: Inspo-paper
 * archetype: Accordion · diversification: native <details>, single-open
 *   behaviour, no JS-only library
 * states: default · hover · open · focus-visible
 * contrast: pass (46-50)
 */

import { useRef } from "react";

/**
 * Accordion — built on native <details>/<summary> so keyboard, screen
 * reader, and no-JS behaviour all work for free. The "single open at a
 * time" pattern is enforced by closing siblings on each toggle. The
 * affordance is a typographic "+ / —" pair, not an SVG chevron.
 */
const QA = [
  {
    q: "Is Inspo free?",
    a: "Yes — open source, MIT, owned by Together AI. Free in every tier. The tiers differ in how much of the stack you run yourself.",
  },
  {
    q: "How do I install the MCP server?",
    a: "`npx inspo init` detects Claude Code, Cursor, Codex, and Zed configs and appends the server entry. It opens your browser once to authenticate the hosted instance.",
  },
  {
    q: "Can I self-host?",
    a: "Every dependency (Postgres, blob storage, the worker) has a free tier or local equivalent. The worker runs anywhere Chromium runs. See /about for the runbook.",
  },
  {
    q: "Where does the catalogue come from?",
    a: "Curated by hand from a seed list of sites. The worker captures three viewports, extracts palette + type ramp + tech, runs a vision-LLM pass for tags, then waits for curator review.",
  },
];

export function FaqAccordion() {
  const ref = useRef<HTMLUListElement>(null);

  function onToggle(e: React.SyntheticEvent<HTMLDetailsElement>) {
    if (!ref.current) return;
    const opened = e.currentTarget;
    if (!opened.open) return;
    ref.current.querySelectorAll<HTMLDetailsElement>("details[open]").forEach((d) => {
      if (d !== opened) d.open = false;
    });
  }

  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <div className="mb-12 grid grid-cols-1 gap-y-3 lg:grid-cols-12 lg:gap-x-10">
        <div className="lg:col-span-3">
          <p className="text-meta">Questions</p>
        </div>
        <p className="lg:col-span-9 font-display max-w-[24ch] text-balance text-4xl leading-[1.05] tracking-tight">
          The ones we&rsquo;re asked most often.
        </p>
      </div>

      <ul ref={ref} className="border-t rule">
        {QA.map(({ q, a }) => (
          <li key={q}>
            <details onToggle={onToggle} className="group border-b rule">
              <summary
                className="
                  flex cursor-pointer items-baseline justify-between gap-6
                  py-5 transition-colors
                  hover:text-[var(--color-link)]
                  focus-visible:outline-none focus-visible:text-[var(--color-link)]
                "
              >
                <p className="font-display text-xl leading-tight sm:text-2xl">
                  {q}
                </p>
                <span
                  aria-hidden
                  className="font-mono text-base text-[var(--color-fg-muted)] transition-transform duration-200 group-open:rotate-45"
                >
                  +
                </span>
              </summary>
              <p className="max-w-[60ch] pb-6 pr-8 text-sm leading-relaxed text-[var(--color-fg-muted)]">
                {a}
              </p>
            </details>
          </li>
        ))}
      </ul>
    </section>
  );
}

"use client";

/* Hallmark · component: faq · genre: editorial · theme: Inspo-paper
 * archetype: Category tabs · diversification: questions sliced by
 *   audience or topic — useful when the FAQ serves multiple roles
 * states: default · hover · active (tab) · focus-visible
 * contrast: pass (46-50)
 */

import { useState } from "react";

const CATEGORIES = {
  Designers: [
    { q: "Can I just browse without an account?", a: "Yes. Everything in the gallery is public — no signup required." },
    { q: "Where do I find palettes?", a: "Open any site detail page; the brand palette band shows the extracted swatches." },
  ],
  Engineers: [
    { q: "How does the MCP server authenticate?", a: "OAuth via the browser on first install — your editor remembers the token after." },
    { q: "Can I run the worker locally?", a: "Yes. Playwright + Chromium on any Node host. See DEPLOY.md." },
  ],
  Curators: [
    { q: "How do I add a site?", a: "Append it to apps/worker/src/seed-urls.ts and open a PR." },
    { q: "Why was a site rejected?", a: "Audit pass flagged a banner, broken capture, or off-brief content. Check the curator note." },
  ],
};

type Cat = keyof typeof CATEGORIES;

export function FaqCategoryTabs() {
  const [active, setActive] = useState<Cat>("Designers");

  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <p className="text-meta">Questions, sliced</p>
      <p
        className="font-display mt-4 max-w-[22ch] text-balance leading-[1.05] tracking-tight"
        style={{ fontSize: "clamp(2rem, 4vw, 3rem)" }}
      >
        Who&rsquo;s asking.
      </p>

      {/* Tabs */}
      <div
        role="tablist"
        aria-label="FAQ categories"
        className="mt-10 flex flex-wrap items-baseline gap-6 border-b rule pb-2"
      >
        {(Object.keys(CATEGORIES) as Cat[]).map((k) => (
          <button
            key={k}
            type="button"
            role="tab"
            aria-selected={active === k}
            onClick={() => setActive(k)}
            className={`
              text-meta relative pb-2
              transition-colors
              ${active === k ? "text-[var(--color-link)]" : "text-[var(--color-fg-muted)] hover:text-[var(--color-fg)]"}
            `}
          >
            {k}
            <span
              aria-hidden
              className={`
                pointer-events-none absolute inset-x-0 -bottom-px h-px bg-[var(--color-link)]
                transition-transform duration-200 origin-left
                ${active === k ? "scale-x-100" : "scale-x-0"}
              `}
            />
          </button>
        ))}
      </div>

      <dl className="mt-8">
        {CATEGORIES[active].map((row) => (
          <div
            key={row.q}
            className="grid grid-cols-1 gap-x-10 gap-y-2 border-b rule py-5 lg:grid-cols-[16rem_1fr]"
          >
            <dt className="font-display text-lg leading-tight">{row.q}</dt>
            <dd className="max-w-[60ch] text-sm leading-relaxed text-[var(--color-fg-muted)]">
              {row.a}
            </dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

"use client";

/* Hallmark · component: faq · genre: editorial · theme: Inspo-paper
 * archetype: Compact list · diversification: Q-only by default, click
 *   to expand A inline — dense list scanning
 * states: default · hover · open · focus-visible
 * contrast: pass (46-50)
 */

import { useState } from "react";

const QA = [
  { q: "Is it free?", a: "Open source, MIT. Free in every tier." },
  { q: "Does it train on my prompts?", a: "No. Search logs are anonymised; we do not retain prompt content." },
  { q: "Can I bring my own catalogue?", a: "Self-host the worker, point it at your seed list. Same schema." },
  { q: "What about images we don't own?", a: "Editorial commentary precedent. Credit + takedown honoured at /dmca." },
  { q: "Is there a desktop app?", a: "No. The MCP runs in your editor — your editor IS the app." },
  { q: "How often does the catalogue grow?", a: "Slowly. Curation is the moat, not coverage." },
];

export function FaqCompact() {
  const [openIdx, setOpenIdx] = useState<number | null>(null);

  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <div className="grid grid-cols-1 gap-x-10 gap-y-3 lg:grid-cols-12">
        <p className="text-meta lg:col-span-3">Brief answers</p>
        <p
          className="lg:col-span-9 font-display max-w-[24ch] text-balance leading-[1.05] tracking-tight"
          style={{ fontSize: "clamp(2rem, 4vw, 3rem)" }}
        >
          The short version of everything.
        </p>
      </div>

      <ul className="mt-12 border-t rule">
        {QA.map((row, i) => {
          const open = openIdx === i;
          return (
            <li key={row.q} className="border-b rule">
              <button
                type="button"
                onClick={() => setOpenIdx(open ? null : i)}
                aria-expanded={open}
                className={`
                  flex w-full items-baseline justify-between gap-6 py-4 text-left
                  transition-colors
                  ${open ? "text-[var(--color-link)]" : "hover:text-[var(--color-link)]"}
                `}
              >
                <p className="font-display text-lg leading-tight sm:text-xl">{row.q}</p>
                <span
                  aria-hidden
                  className={`font-mono text-sm transition-transform duration-200 ${open ? "rotate-45" : ""}`}
                >
                  +
                </span>
              </button>
              {open && (
                <p className="max-w-[60ch] pb-5 text-sm leading-relaxed text-[var(--color-fg-muted)]">
                  {row.a}
                </p>
              )}
            </li>
          );
        })}
      </ul>
    </section>
  );
}

/* Hallmark · component: faq · genre: editorial · theme: Inspo-paper
 * archetype: Numbered list · diversification: differs from Accordion +
 *   Two-column on hierarchy (ordered list vs paired columns)
 * states: default (static)
 * contrast: pass (46-50)
 */

/**
 * Numbered FAQ — the questions read as a list of arguments. Numbered
 * prefix in mono, question in display weight, answer flush-left
 * underneath. No collapsing, no chrome. Reads like a manifesto's
 * "frequently asked, briefly answered."
 */
const QA = [
  {
    q: "Is the catalogue ever-growing?",
    a: "Yes — but slowly. Curation is the moat, not coverage.",
  },
  {
    q: "Can I submit a site?",
    a: "Soon. v1 is curator-only; v2 opens an /extract endpoint with auth + rate-limiting.",
  },
  {
    q: "Does it work offline?",
    a: "The catalogue ships baked into the bundle as static JSON, so /screens and /sites render without a database. Search remains client-side.",
  },
];

export function FaqNumbered() {
  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <p className="text-meta">Asked, briefly answered</p>
      <ol className="mt-12 space-y-12">
        {QA.map((row, i) => (
          <li
            key={row.q}
            className="grid grid-cols-1 gap-x-10 gap-y-2 lg:grid-cols-[5rem_1fr]"
          >
            <span
              className="font-mono text-meta text-[var(--color-fg-muted)]"
              aria-hidden
            >
              {String(i + 1).padStart(2, "0")}
            </span>
            <div>
              <p className="font-display text-2xl leading-tight sm:text-3xl">
                {row.q}
              </p>
              <p className="mt-3 max-w-[58ch] text-sm leading-relaxed text-[var(--color-fg-muted)]">
                {row.a}
              </p>
            </div>
          </li>
        ))}
      </ol>
    </section>
  );
}

/* Hallmark · component: faq · genre: editorial · theme: Inspo-paper
 * archetype: Two-column open · diversification: differs from Accordion
 *   on interaction (none — all open) + structure (Q-left, A-right)
 * states: default (static)
 * contrast: pass (46-50)
 */

/**
 * Two-column open — every Q&A on display, no toggle. Question sits in
 * the left column, answer in the right. Reads as a magazine Q&A
 * interview, not a help-desk FAQ. Good when the questions are short
 * and the answers are the meat.
 */
const QA = [
  {
    q: "Why open source?",
    a: "Because the reference layer should belong to the field, not a vendor. MIT, owned by Together AI, free to fork.",
  },
  {
    q: "Why MCP and not a REST API?",
    a: "Both, actually. The MCP wraps the same query surface a REST API exposes — the value is in the catalogue, not the protocol.",
  },
  {
    q: "Who is this for?",
    a: "Designers and the coding agents they work alongside. The website is for humans — browse, study, copy a DESIGN.md. The MCP is for agents — same catalogue, addressed by tool calls.",
  },
  {
    q: "What about copyright?",
    a: "Screenshots of public web pages for editorial commentary is well-established. We credit designers and respect takedown requests.",
  },
];

export function FaqTwoColumn() {
  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <div className="mb-12 grid grid-cols-1 gap-y-3 lg:grid-cols-12 lg:gap-x-10">
        <div className="lg:col-span-3">
          <p className="text-meta">FAQ</p>
        </div>
        <p className="lg:col-span-9 font-display max-w-[26ch] text-balance text-4xl leading-[1.05] tracking-tight">
          The ones worth answering out loud.
        </p>
      </div>

      <dl className="border-t rule">
        {QA.map((row) => (
          <div
            key={row.q}
            className="grid grid-cols-1 gap-x-10 gap-y-3 border-b rule py-8 lg:grid-cols-12"
          >
            <dt className="lg:col-span-4">
              <p className="font-display text-2xl leading-tight">{row.q}</p>
            </dt>
            <dd className="lg:col-span-8">
              <p className="max-w-[60ch] text-sm leading-relaxed text-[var(--color-fg-muted)]">
                {row.a}
              </p>
            </dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

/* Hallmark · component: features · genre: editorial · theme: Inspo-paper
 * archetype: Alternating rows · diversification: differs from Bento +
 *   triplet on structure (vertical scroll vs grid) + density (low vs high)
 * states: default (static)
 * contrast: pass (46-50)
 */

/**
 * Alternating rows — three feature blocks stacked vertically, label
 * slot flipping side per row to break the column rhythm. No images;
 * a typographic mark (lettered ordinal in mono) sits where the image
 * would. The shape comes from the alternation, not asset variety.
 */
const ROWS = [
  {
    mark: "A",
    label: "Search the way you think",
    body: "Type a mood. Paste a URL. Hit ⌘K. The catalogue answers however you ask it — lex, vector, hostname. Hybrid retrieval is the unsexy choice that works.",
  },
  {
    mark: "B",
    label: "Tag, but only what's true",
    body: "Tags live behind a hard allow-list. Style, industry, vibe, color words. A pricing card that isn't pricing is worse than no pricing card.",
  },
  {
    mark: "C",
    label: "Return URLs, not base64",
    body: "The MCP hands back image URLs your agent's vision model can fetch directly. No context bloat. No 200KB of base64 in the tool result.",
  },
];

export function FeaturesAlternating() {
  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <ul className="space-y-16">
        {ROWS.map((r, i) => {
          const flip = i % 2 === 1;
          return (
            <li
              key={r.mark}
              className={`
                grid grid-cols-1 items-baseline gap-x-12 gap-y-6
                ${flip ? "md:[grid-template-columns:1fr_4fr]" : "md:[grid-template-columns:4fr_1fr]"}
              `}
            >
              <div className={flip ? "md:order-1 md:text-right" : "md:order-2"}>
                <span
                  className="font-display inline-block leading-none text-[var(--color-fg-muted)]"
                  style={{ fontSize: "clamp(4rem, 8vw, 7rem)" }}
                >
                  {r.mark}
                </span>
              </div>
              <div className={flip ? "md:order-2" : "md:order-1"}>
                <p className="text-meta">Section {r.mark}</p>
                <p className="font-display mt-3 max-w-[24ch] text-balance text-3xl leading-[1.05] tracking-tight sm:text-4xl">
                  {r.label}
                </p>
                <p className="mt-4 max-w-[58ch] text-sm leading-relaxed text-[var(--color-fg-muted)]">
                  {r.body}
                </p>
              </div>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

/* Hallmark · component: features · genre: editorial · theme: Inspo-paper
 * archetype: Icon trio · diversification: three features each carrying
 *   a typographic mark — no SVG iconography
 * states: default + hover (mark colour shift)
 * contrast: pass (46-50)
 *
 * Hallmark note: rotational SVG iconography (rounded squares + line
 * icons) is one of the strongest AI fingerprints. The typographic
 * marks here (a single mono letter inside a hairline square) carry
 * the same hierarchy without the slop tell.
 */

const ITEMS = [
  {
    mark: "S",
    label: "Search",
    body: "Type a mood, paste a URL, hit ⌘K. Hybrid lex + vector retrieval over the catalogue.",
  },
  {
    mark: "C",
    label: "Crop",
    body: "Every captured page has its component regions cropped — heroes, pricing, footers — addressable from the MCP.",
  },
  {
    mark: "D",
    label: "DESIGN.md",
    body: "Per-site design system extracted from the DOM. Palette roles, type ramp, spacing. Your agent reads it directly.",
  },
];

export function FeaturesIconTrio() {
  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <p className="text-meta">Three primitives</p>
      <p
        className="font-display mt-4 max-w-[22ch] text-balance leading-[1.05] tracking-tight"
        style={{ fontSize: "clamp(2rem, 4.5vw, 3.5rem)" }}
      >
        Search, Crop, DESIGN.md.
      </p>

      <ul className="mt-16 grid grid-cols-1 gap-x-10 gap-y-12 md:grid-cols-3">
        {ITEMS.map((i) => (
          <li key={i.mark} className="group">
            <div
              className="
                inline-flex h-14 w-14 items-center justify-center border-2 rule
                font-display text-3xl
                transition-colors
                group-hover:border-[var(--color-link)] group-hover:text-[var(--color-link)]
              "
            >
              {i.mark}
            </div>
            <p className="font-display mt-6 text-2xl leading-tight">{i.label}</p>
            <p className="mt-3 max-w-[40ch] text-sm leading-relaxed text-[var(--color-fg-muted)]">
              {i.body}
            </p>
          </li>
        ))}
      </ul>
    </section>
  );
}

/* Hallmark · component: features · genre: editorial · theme: Inspo-paper
 * archetype: Long-form prose · diversification: features described as
 *   essay paragraphs, not bullet points
 * states: default (static)
 * contrast: pass (46-50)
 */

/**
 * Long-form prose — features written as connected paragraphs in a
 * single column with marginal headings. The default AI-page output
 * is a 3-column feature grid; this is the alternative when the brand
 * voice deserves to be read, not scanned.
 */
const NOTES = [
  {
    label: "On reading the page",
    body: "Inspo treats the catalogue as a magazine archive: every site has a credit line, every plate sits at full resolution, every detail page reads like a back-of-the-issue colophon. Scroll the gallery slowly. Open the ones that stop you.",
  },
  {
    label: "On talking to your agent",
    body: "The MCP server hands the same catalogue to Claude Code, Cursor, Codex, and Zed as tool calls. Search by mood, paste a URL, pull a DESIGN.md — the agent sees what you see, and writes from that reference instead of from training-data averages.",
  },
  {
    label: "On the reference layer",
    body: "The components page is the second surface: twenty-eight Hallmark-disciplined sections, each one stamped with its macrostructure. Copy the markup, study the rule, and your output stops looking like every other AI page.",
  },
];

export function FeaturesLongForm() {
  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <p className="text-meta">Three notes</p>
      <p
        className="font-display mt-4 max-w-[20ch] text-balance leading-[1.05] tracking-tight"
        style={{ fontSize: "clamp(2rem, 4.5vw, 3.5rem)" }}
      >
        How this is meant to be used.
      </p>

      <div className="mt-16 space-y-14">
        {NOTES.map((n) => (
          <div
            key={n.label}
            className="grid grid-cols-1 gap-x-10 gap-y-3 lg:grid-cols-12"
          >
            <p className="text-meta lg:col-span-3">{n.label}</p>
            <p className="lg:col-span-9 max-w-[64ch] text-base leading-relaxed text-[var(--color-fg)]">
              {n.body}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
}

/* Hallmark · component: features · genre: editorial · theme: Inspo-paper
 * archetype: Numbered triplet · diversification: differs from Bento on
 *   structure (equal columns vs irregular spans) + voice (process vs catalog)
 * states: default (static)
 * contrast: pass (46-50)
 */

/**
 * Numbered triplet — three steps, each prefaced by a big mono ordinal.
 * Reads like a process diagram without a diagram. Each column is the
 * same width; the variety comes from the type, not the layout.
 */
const STEPS = [
  {
    n: "01",
    label: "Browse",
    body: "Open the archive. Filter by mood, paste a URL, scroll until something stops you.",
  },
  {
    n: "02",
    label: "Study",
    body: "Each tile lifts to a site detail page — palette, type ramp, components, designer credit.",
  },
  {
    n: "03",
    label: "Build",
    body: "Hand the design system to your agent over MCP — or copy DESIGN.md to clipboard yourself.",
  },
];

export function FeaturesNumberedTriplet() {
  return (
    <section className="border rule bg-[var(--color-bg)] px-8 py-16 sm:px-14 sm:py-20">
      <p className="text-meta">How to use it</p>
      <p className="font-display mt-6 max-w-[24ch] text-balance text-4xl leading-[1.05] tracking-tight sm:text-5xl">
        Three steps, no signup.
      </p>

      <ol className="mt-16 grid grid-cols-1 gap-x-10 gap-y-12 md:grid-cols-3">
        {STEPS.map((s) => (
          <li key={s.n} className="border-t-2 border-[var(--color-fg)] pt-6">
            <p
              className="font-mono text-[var(--color-fg-muted)]"
              style={{
                fontSize: "0.7rem",
                letterSpacing: "0.12em",
                textTransform: "uppercase",
              }}
            >
              Step {s.n}
            </p>
            <p className="font-display mt-3 text-3xl leading-tight tracking-tight">
              {s.label}
            </p>
            <p className="mt-4 max-w-[42ch] text-sm leading-relaxed text-[var(--color-fg-muted)]">
