          </a>
          <button
            type="button"
            onClick={() => setOpen(true)}
            aria-expanded={open}
            aria-controls="off-canvas-nav"
            className="text-meta border rule px-3 py-1.5 transition-colors hover:border-[var(--color-link)] hover:text-[var(--color-link)]"
          >
            Menu
          </button>
        </div>
